begin;
do $test$
#variable_conflict use_variable
declare owner_id uuid:='fad75b91-d2eb-4805-b5a3-c19e8a073bed';child_id uuid:='3666b777-1066-4eb7-a0c3-f63c2e01ae90';member_id uuid;
 event_id uuid:=gen_random_uuid();album_id uuid:=gen_random_uuid();media_id uuid:=gen_random_uuid();product_id uuid:=gen_random_uuid();order_id uuid:=gen_random_uuid();group_id uuid:=gen_random_uuid();ticket_id uuid:=gen_random_uuid();r jsonb;n int;balance numeric;before_state jsonb;after_state jsonb;cursor_date timestamptz;cursor_id uuid;
begin
 select user_id into strict member_id from public.filhos_de_santo where id=child_id and tenant_id=owner_id;
 select coalesce(sum(valor),0) into balance from public.financeiro where tenant_id=owner_id;
 insert into public.calendario_axe(id,tenant_id,lider_id,titulo,data,hora,tipo,status_confirmacao,vagas_maximas) values(event_id,owner_id,owner_id,'VALIDACAO-CODEX-ROLLBACK','2099-01-01','20:00','Gira','Confirmado',1);
 insert into public.gallery_albums(id,tenant_id,name) values(album_id,owner_id,'VALIDACAO-CODEX-ROLLBACK');
 insert into public.gallery_media(id,tenant_id,album_id,media_type,file_name,mime_type,storage_key,public_url) values(media_id,owner_id,album_id,'image','technical.png','image/png','VALIDACAO-CODEX/'||media_id::text,'https://example.invalid/technical.png');
 insert into public.produtos(id,tenant_id,nome,preco,estoque_atual) values(product_id,owner_id,'VALIDACAO-CODEX-ROLLBACK',1,2);
 insert into public.pedidos(id,tenant_id,filho_id,total,status,metodo_pagamento) values(order_id,owner_id,child_id,1,'pendente','mensalidade');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);execute 'set local role authenticated';
 r:=public.piloto_definir_capa(owner_id,album_id,media_id);if r->>'media_id'<>media_id::text then raise exception 'Capa não confirmada';end if;
 begin perform public.piloto_definir_capa(owner_id,album_id,gen_random_uuid());raise exception 'Capa de outro álbum foi aceita';exception when invalid_parameter_value then null;end;
 before_state:='{"highlight":false,"tasks":[],"noticeDraft":"","noticeSaved":false}';after_state:='{"highlight":true,"tasks":["materiais"],"noticeDraft":"Orientações","noticeSaved":true}';
 perform public.piloto_preparar_gira(owner_id,event_id,after_state,before_state);
 r:=public.piloto_preparar_gira(owner_id,event_id,after_state,before_state);if r->>'replayed'<>'true' then raise exception 'Preparação não é idempotente';end if;
 begin perform public.piloto_preparar_gira(owner_id,event_id,before_state,before_state);raise exception 'Preparação antiga sobrescreveu estado novo';exception when unique_violation then null;end;
 begin perform public.piloto_preparar_gira(owner_id,event_id,after_state||'{"tasks":["materiais","materiais"]}',after_state);raise exception 'Aceitou etapa duplicada';exception when invalid_parameter_value then null;end;
 r:=public.piloto_emitir_senha(owner_id,event_id,ticket_id,'Consulente técnico','');if r->>'numero'<>'1' then raise exception 'Numeração incorreta';end if;
 r:=public.piloto_emitir_senha(owner_id,event_id,ticket_id,'Consulente técnico','');if r->>'replayed'<>'true' then raise exception 'Repetição duplicou senha';end if;
 begin perform public.piloto_emitir_senha(owner_id,event_id,gen_random_uuid(),'Segunda pessoa','');raise exception 'Ultrapassou a capacidade';exception when invalid_parameter_value then null;end;
 before_state:='{"marks":{},"closed":false}';after_state:=jsonb_build_object('marks',jsonb_build_object(child_id::text,'excused'),'closed',true);
 perform public.piloto_salvar_chamada(owner_id,event_id,after_state,before_state);
 r:=public.piloto_salvar_chamada(owner_id,event_id,after_state,before_state);if r->>'replayed'<>'true' then raise exception 'Chamada duplicada';end if;
 begin perform public.piloto_salvar_chamada(owner_id,event_id,before_state,before_state);raise exception 'Chamada antiga sobrescreveu nova';exception when unique_violation then null;end;
 if not exists(select 1 from public.evento_participantes where evento_participantes.event_id=event_id and filho_id=child_id and status='recusado' and justificativa='Ausência justificada pela zeladoria') then raise exception 'Presença não persistiu';end if;
 perform public.piloto_arquivar_produto(owner_id,product_id,true,false);
 if not exists(select 1 from public.produtos where id=product_id and deleted_at is not null and estoque_atual=2) then raise exception 'Arquivar alterou estoque';end if;
 perform public.piloto_arquivar_produto(owner_id,product_id,false,true);
 perform public.piloto_marcar_entrega(owner_id,order_id,true,false);
 if not exists(select 1 from public.pedidos where id=order_id and status='pendente' and total=1) then raise exception 'Entrega alterou pagamento';end if;
 execute 'reset role';update public.pedidos set status='cancelado' where id=order_id;execute 'set local role authenticated';
 if exists(select 1 from public.piloto_entregas_pedidos where pedido_id=order_id and entregue) then raise exception 'Cancelamento manteve entrega';end if;
 begin perform public.piloto_marcar_entrega(owner_id,order_id,true,false);raise exception 'Entregou pedido cancelado';exception when invalid_parameter_value then null;end;
 r:=public.piloto_criar_grupo(owner_id,group_id,'VALIDACAO-CODEX-ROLLBACK',array[child_id]);if r->>'conversationId'<>group_id::text then raise exception 'Grupo não confirmado';end if;
 r:=public.piloto_criar_grupo(owner_id,group_id,'VALIDACAO-CODEX-ROLLBACK',array[child_id]);if r->>'replayed'<>'true' then raise exception 'Grupo duplicado';end if;
 select count(*) into n from public.chat_participants where conversation_id=group_id;if n<>2 then raise exception 'Grupo incluiu pessoas não selecionadas';end if;
 perform public.piloto_arquivar_conversa(owner_id,group_id,true);perform public.piloto_marcar_conversa(owner_id,group_id,true);
 if not exists(select 1 from public.piloto_chat_preferencias where conversa_id=group_id and arquivada and nao_lida) then raise exception 'Preferências da conversa não persistiram';end if;
 execute 'reset role';
 insert into public.chat_messages(id,tenant_id,conversation_id,sender_user_id,body,message_type,created_at) select gen_random_uuid(),owner_id,group_id,owner_id,'technical '||i,'text','2099-01-01T00:00:00Z'::timestamptz from generate_series(1,105) i;
 execute 'set local role authenticated';r:=public.piloto_mensagens(owner_id,group_id,null,null);if jsonb_array_length(r->'messages')<>101 or r->>'hasMore'<>'true' then raise exception 'Primeira página incompleta';end if;
 cursor_date:=(r->'messages'->99->>'created_at')::timestamptz;cursor_id:=(r->'messages'->99->>'id')::uuid;
 r:=public.piloto_mensagens(owner_id,group_id,cursor_date,cursor_id);if jsonb_array_length(r->'messages')<>5 or r->>'hasMore'<>'false' then raise exception 'Cursor perdeu mensagens de mesmo horário';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',member_id,'role','authenticated')::text,true);
 select count(*) into n from public.piloto_capas_galeria where piloto_capas_galeria.album_id=album_id;if n<1 then raise exception 'Membro não pode ler capa';end if;
 select count(*) into n from public.piloto_chat_preferencias;if n<>0 then raise exception 'Preferência do zelador exposta ao membro';end if;
 begin perform public.piloto_arquivar_produto(owner_id,product_id,true,false);raise exception 'Membro arquivou produto';exception when insufficient_privilege then null;end;
 begin perform public.piloto_emitir_senha(owner_id,event_id,gen_random_uuid(),'Não autorizado','');raise exception 'Membro emitiu senha';exception when insufficient_privilege then null;end;
 begin perform public.piloto_mensagens(owner_id,group_id,null,null);raise exception 'Membro usou rota de zelador';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
 select count(*) into n from public.piloto_capas_galeria;if n<>0 then raise exception 'Outra casa leu capa privada';end if;
 begin perform public.piloto_arquivar_conversa(owner_id,group_id,true);raise exception 'Outra casa alterou preferências';exception when insufficient_privilege then null;end;
 execute 'reset role';
 if balance is distinct from (select coalesce(sum(valor),0) from public.financeiro where tenant_id=owner_id) then raise exception 'Operação sem pagamento alterou o caixa';end if;
end $test$;
rollback;
select 'passed' as pilot_manager_operations_validation,'all fixtures and DDL rolled back in rehearsal' as persistence;
